import zipfile, xml.etree.ElementTree as ET, re

xlsx_files = [
    '/workspace/testbed/data/budget.xlsx',
    '/workspace/testbed/data/travel_expenses.xlsx',
    '/workspace/testbed/data/product_inventory.xlsx',
    '/workspace/testbed/data/order_summary.xlsx',
]

for fpath in xlsx_files:
    print(f'=== {fpath} ===')
    try:
        with zipfile.ZipFile(fpath) as z:
            # Get shared strings
            shared = []
            if 'xl/sharedStrings.xml' in z.namelist():
                with z.open('xl/sharedStrings.xml') as f:
                    tree = ET.parse(f)
                    ns = {'s': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
                    for si in tree.findall('.//s:si', ns):
                        texts = [t.text for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t') if t.text]
                        shared.append(''.join(texts))

            # Check shared strings for zip patterns
            found = False
            for s in shared:
                if re.search(r'\b\d{5}(-\d{4})?\b', s) or re.search(r'(?i)(zip|postal|address)', s):
                    print(f'  SharedString: {s}')
                    found = True

            # Also check sheet data for inline strings and values
            for name in z.namelist():
                if name.startswith('xl/worksheets/'):
                    with z.open(name) as f:
                        tree = ET.parse(f)
                        ns = {'s': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
                        for row in tree.findall('.//s:row', ns):
                            for c in row.findall('s:c', ns):
                                v = c.find('s:v', ns)
                                if v is not None and v.text and re.search(r'\b\d{5}(-\d{4})?\b', v.text):
                                    print(f'  {name} cell {c.get(\"r\")}: {v.text}')
                                    found = True
            if not found:
                print('  No zip code patterns found')
    except Exception as e:
        print(f'  Error: {e}')
    print()
